<?php require_once __DIR__.'/../classes/Database.php';require_once __DIR__.'/../classes/Auth.php';require_once __DIR__.'/../classes/Session.php';Session::start();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$q=(new Database())->getConnection()->prepare('SELECT * FROM administrateur WHERE email=:e LIMIT 1');$q->execute(['e'=>trim($_POST['email']??'')]);$a=$q->fetch();if($a&&Auth::verifyPassword($_POST['mot_de_passe']??'',$a['mot_de_passe'])){Session::set('admin_id',$a['id']);Session::set('admin_nom',$a['prenom']);Session::set('admin_connecte',true);header('Location: dashboard.php');exit;}$err='Identifiants incorrects.';}?><!doctype html><html lang="fr"><head><meta charset="UTF-8"><title>Admin</title></head><body><h1>Connexion administrateur</h1><?php if($err):?><p><?=htmlspecialchars($err)?></p><?php endif;?><form method="post"><input type="email" name="email" required><input type="password" name="mot_de_passe" required><button>Se connecter</button></form></body></html>